"""Generated bytes must be readable under the same saved-file limits."""

import importlib
from pathlib import Path
import subprocess
import sys

import pytest

EXAMPLES = Path(__file__).resolve().parents[4] / "examples"


@pytest.mark.parametrize("module,args", [
    ("generate_shading", ["--rows", "1", "--cols", "1", "--rules", "no-white-2x2"]),
    ("generate_slitherlink", ["--rows", "1", "--cols", "1"]),
    ("generate_yajilin", []),
])
def test_generated_file_and_stdout_keep_exact_checked_bytes_at_limit(
        tmp_path, monkeypatch, capfdbinary, module, args):
    monkeypatch.syspath_prepend(str(EXAMPLES))
    app = importlib.import_module(module)
    records = importlib.import_module("json_records")
    original_encode = records.encode_json

    def encode_at_limit(data):
        data["environment"]["test_padding"] = ""
        data["environment"]["test_padding"] = "x" * (records.MAX_BYTES - len(original_encode(data)))
        return original_encode(data)

    monkeypatch.setattr(app, "encode_json", encode_at_limit)
    path = tmp_path / "boundary.json"
    monkeypatch.setattr(sys, "argv", [module, "generate", *args, "--output", str(path)])
    assert app.main() == 0
    output = capfdbinary.readouterr()
    raw = path.read_bytes()
    assert len(raw) == records.MAX_BYTES
    assert output.out == raw and output.err == b""
    assert b"\r\n" not in raw  # No Windows newline expansion after size checking.
    assert app.verify(records.load_json(path))["valid"]


@pytest.mark.parametrize("destination", ["stdout", "new-file", "existing-file"])
def test_large_rule_list_fails_before_writing_or_reporting_success(tmp_path, destination):
    path = tmp_path / "puzzle.json"
    if destination == "existing-file":
        path.write_bytes(b"keep existing data")
    output = [] if destination == "stdout" else ["--output", str(path)]
    if destination == "new-file":
        output.append("--quiet")
    result = subprocess.run(
        [sys.executable, str(EXAMPLES / "generate_shading.py"), "generate",
         "--rows", "1", "--cols", "1", "--seed", "0", *output,
         "--rules", *(["no-white-2x2"] * 2000)],
        capture_output=True, timeout=30,
    )
    assert result.returncode == 2
    assert b"at most 65536 bytes" in result.stderr
    assert b"Traceback" not in result.stderr and result.stdout == b""
    if destination == "existing-file":
        assert path.read_bytes() == b"keep existing data"
    else:
        assert not path.exists()


def test_one_byte_above_the_limit_is_rejected(monkeypatch):
    monkeypatch.syspath_prepend(str(EXAMPLES))
    records = importlib.import_module("json_records")
    data = {"environment": {"note": ""}}
    data["environment"]["note"] = "x" * (records.MAX_BYTES + 1 - len(records.encode_json(data)))
    with pytest.raises(ValueError, match="at most 65536 bytes"):
        records.encode_json(data)


@pytest.mark.parametrize("number", [float("nan"), float("inf"), -float("inf")])
def test_encoder_does_not_write_numbers_rejected_by_the_reader(monkeypatch, number):
    monkeypatch.syspath_prepend(str(EXAMPLES))
    records = importlib.import_module("json_records")
    with pytest.raises(ValueError):
        records.encode_json({"environment": {"number": number}})
